CREATE OR REPLACE FUNCTION eflow_r7.node_capabilities_fast(p_root uuid, p_node uuid, p_root_json jsonb, p_eligible boolean, p_head boolean, p_plan_lead boolean, p_staffing_locked boolean, p_actor_member boolean, p_root_lead_member boolean, p_dirty_ids uuid[], p_project_status text, p_invalid_tree boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  n eflow_r7.nodes;
  actions text[] := array['manage_contributors','appoint_lead','create_child','edit_details','move','order_children','delete','execute','submit','review'];
  action text;
  reason text;
  common_reason text;
  result jsonb := '{}';
  manager boolean := false;
  untouched boolean := true;
  descendants_complete boolean := true;
  ordered_ready boolean := true;
  node_depth integer := 1;
  v_subtree_ids uuid[] := '{}';
  v_child_subtree_ids uuid[] := '{}';
  v_move_ids uuid[] := '{}';
  v_kind text := p_root_json->>'kind';
  v_open boolean := coalesce((p_root_json->>'open')::boolean, false);
  v_root_lead uuid := (p_root_json->>'lead')::uuid;
  v_proj uuid := (p_root_json->>'project')::uuid;
  v_office uuid := (p_root_json->>'office')::uuid;
  v_chain_parent boolean := false;
  v_chain_self boolean := false;
  v_node_work boolean := false;
  v_manage_plan boolean := false;
  v_replace_lead_plan boolean := false;
  v_can_edit_details boolean := false;
  v_dep_ids uuid[];
  v_activated boolean := false;
begin
  if p_root_json is null or v_uid is null then
    common_reason := 'access_unavailable';
  elsif not p_eligible then
    common_reason := 'read_only';
  elsif not v_open then
    common_reason := 'lifecycle_blocked';
  end if;

  select * into n from eflow_r7.nodes where id = p_node and task_id = p_root;
  if not found then
    common_reason := 'access_unavailable';
  end if;

  if common_reason is null then
    with recursive below as (
      select * from eflow_r7.nodes where id = p_node and task_id = p_root
      union all
      select c.* from eflow_r7.nodes c join below b on c.parent_subtask_id = b.id where c.task_id = p_root
    )
    select
      coalesce(array_agg(id), '{}'),
      not exists(select 1 from below where status <> 'todo' or percent_complete <> 0),
      not exists(select 1 from below where id <> p_node and status <> 'completed')
    into v_subtree_ids, untouched, descendants_complete
    from below;

    with recursive above as (
      select id, parent_subtask_id, lead_id, 1 depth from eflow_r7.nodes where id = p_node and task_id = p_root
      union all
      select c.id, c.parent_subtask_id, c.lead_id, a.depth + 1 from eflow_r7.nodes c join above a on c.id = a.parent_subtask_id where c.task_id = p_root and a.depth < 8
    )
    select max(depth) into node_depth from above;

    v_chain_parent := eflow_r7.chain(p_root, n.parent_subtask_id);
    if n.parent_subtask_id is not null then
      v_chain_self := eflow_r7.chain(p_root, p_node);
    else
      v_chain_self := p_root_lead_member and n.lead_id is not null and eflow_r7.member(v_proj, v_office, n.lead_id);
    end if;

    if p_head then
      manager := true;
    elsif p_actor_member then
      if v_root_lead = v_uid then
        manager := true;
      elsif v_chain_self then
        manager := exists(
          with recursive anc as (
            select id, parent_subtask_id, lead_id from eflow_r7.nodes where id = p_node and task_id = p_root
            union all
            select c.id, c.parent_subtask_id, c.lead_id from eflow_r7.nodes c join anc a on c.id = a.parent_subtask_id where c.task_id = p_root
          ) select 1 from anc where lead_id = v_uid
        );
      end if;
    end if;

    v_manage_plan := manager or p_plan_lead;
    if p_head then
      v_replace_lead_plan := true;
    elsif p_plan_lead then
      v_replace_lead_plan := true;
    elsif p_actor_member then
      if v_root_lead = v_uid then
        v_replace_lead_plan := true;
      elsif n.parent_subtask_id is not null and v_chain_parent then
        v_replace_lead_plan := exists(
          with recursive anc as (
            select id, parent_subtask_id, lead_id from eflow_r7.nodes where id = n.parent_subtask_id and task_id = p_root
            union all
            select c.id, c.parent_subtask_id, c.lead_id from eflow_r7.nodes c join anc a on c.id = a.parent_subtask_id where c.task_id = p_root
          ) select 1 from anc where lead_id = v_uid
        );
      end if;
    end if;

    v_node_work := p_eligible and p_actor_member and v_chain_parent and (
      v_uid = any(coalesce(n.assigned_to_ids, '{}'::uuid[]))
      or (n.kind = 'office' and v_kind = 'office' and n.lead_id = v_uid and v_chain_self)
    );

    ordered_ready := n.is_standalone or not exists(
      select 1 from eflow_r7.nodes c
      where c.task_id = p_root and c.parent_subtask_id is not distinct from n.parent_subtask_id
        and c.sibling_order < n.sibling_order and not c.is_standalone and c.status <> 'completed'
    );
    if v_kind = 'office' then
      select s.dependency_ids,
        (p_root_json->>'status' not in ('todo', 'pending_assignment') and (s.started_at is not null or s.status in ('in_progress','stuck','changes_requested','for_review','completed')))
      into v_dep_ids, v_activated
      from public.subtasks s where s.id = p_node and s.task_id = p_root;
      if v_dep_ids is not null then
        ordered_ready := eflow_r7.subtask_dependencies_ready(p_root, v_dep_ids);
      end if;
      if n.status in ('todo', 'in_progress', 'changes_requested') then
        v_can_edit_details := v_manage_plan;
      end if;
    else
      v_activated := (p_root_json->>'status' <> 'todo') and exists(
        select 1 from public.personal_subtasks s where s.id = p_node and s.task_id = p_root
          and (s.started_at is not null or s.status in ('in_progress','changes_requested','for_review','completed'))
      );
    end if;

    with recursive child_sub as (
      select id from eflow_r7.nodes where task_id = p_root and parent_subtask_id is not distinct from p_node
      union all
      select c.id from eflow_r7.nodes c join child_sub cs on c.parent_subtask_id = cs.id where c.task_id = p_root
    ) select coalesce(array_agg(id), '{}') into v_child_subtree_ids from child_sub;

    with recursive sib_sub as (
      select id from eflow_r7.nodes where task_id = p_root and parent_subtask_id is not distinct from n.parent_subtask_id
      union all
      select c.id from eflow_r7.nodes c join sib_sub ss on c.parent_subtask_id = ss.id where c.task_id = p_root
    ) select coalesce(array_agg(id), '{}') || case when n.parent_subtask_id is not null then array[n.parent_subtask_id] else '{}'::uuid[] end into v_move_ids from sib_sub;
  end if;

  foreach action in array actions loop
    reason := common_reason;
    if reason is null then
      if action in ('appoint_lead', 'manage_contributors')
         and p_staffing_locked
         and v_root_lead is distinct from v_uid
         and (action = 'appoint_lead' or n.lead_id is distinct from v_uid) then
        reason := 'active_subtask_staffing_locked';
      elsif action = 'appoint_lead' then
        if not v_replace_lead_plan then reason := 'appointment_denied';
        elsif n.status = 'completed' then reason := 'lifecycle_blocked';
        end if;
      elsif action in ('execute', 'submit') and v_kind = 'office' and p_project_status in ('planning', 'on_hold') then
        reason := case when p_project_status = 'on_hold' then 'project_on_hold' else 'lifecycle_blocked' end;
      elsif action in ('execute', 'submit') then
        if not manager and (action = 'submit' or not v_node_work) then reason := 'branch_denied';
        elsif n.status = 'completed' or (v_kind = 'office' and p_root_json->>'status' not in ('todo', 'in_progress', 'changes_requested')) then reason := 'lifecycle_blocked';
        elsif not ordered_ready or (action = 'submit' and not descendants_complete) then reason := 'lifecycle_blocked';
        end if;
      elsif action = 'review' then
        reason := 'lifecycle_blocked';
      elsif action = 'manage_contributors' and not v_manage_plan then
        reason := 'branch_denied';
      elsif not v_manage_plan then
        reason := 'branch_denied';
      elsif action = 'manage_contributors' then
        if n.lead_id is null or n.status = 'completed' then reason := 'lifecycle_blocked'; end if;
      elsif action = 'create_child' then
        if n.status <> 'todo' or n.percent_complete <> 0 or node_depth >= 8 then reason := 'lifecycle_blocked'; end if;
      elsif action = 'order_children' then
        if exists(select 1 from eflow_r7.nodes c where c.task_id = p_root and c.parent_subtask_id is not distinct from p_node and (c.status <> 'todo' or c.percent_complete <> 0)) then
          reason := 'lifecycle_blocked';
        end if;
      elsif action = 'edit_details' and v_kind = 'office' then
        if not v_can_edit_details then reason := 'lifecycle_blocked'; end if;
      elsif action in ('edit_details', 'move', 'delete') then
        if not untouched then
          reason := 'lifecycle_blocked';
        elsif action = 'delete' and v_kind = 'office' and (v_subtree_ids && p_dirty_ids) then
          reason := 'history_blocked';
        end if;
      end if;
    end if;

    if reason is null and action in ('execute', 'submit') and not v_activated then
      reason := 'lifecycle_blocked';
    end if;

    if reason is null and action in ('create_child', 'order_children', 'move', 'delete') then
      if p_invalid_tree then
        raise exception 'Work hierarchy has a cycle, foreign parent or depth beyond 8; resolve it first' using errcode = '23514';
      end if;
      if action in ('create_child', 'delete') and (v_subtree_ids && p_dirty_ids) then
        reason := 'history_blocked';
      elsif action = 'order_children' and (v_child_subtree_ids && p_dirty_ids) then
        reason := 'history_blocked';
      elsif action = 'move' and (v_move_ids && p_dirty_ids) then
        reason := 'history_blocked';
      end if;
    end if;

    result := result || jsonb_build_object(action, jsonb_build_object('allowed', reason is null, 'reason_code', reason));
  end loop;

  return result;
end $function$

CREATE OR REPLACE FUNCTION public.submit_task_for_review(p_task_id uuid, p_submission jsonb)
 RETURNS tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  caller_name text;
  completion_note text;
  submission_id uuid;
  submission_version int;
  attachment jsonb;
  normalized_submission jsonb;
  t public.tasks;
  resolved_reviewer uuid;
begin /* NW5.2 shared writer lock */ perform eflow_r7.lock_impact(p_task_id); /* NW4.2 completion serialization */ perform eflow_r7.lock_completion(p_task_id);
  if caller is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  completion_note := nullif(btrim(p_submission ->> 'note'), '');
  if completion_note is null then
    raise exception 'Completion note is required' using errcode = '22023';
  end if;
  if p_submission ? 'attachments'
     and jsonb_typeof(p_submission -> 'attachments') <> 'array' then
    raise exception 'Submission attachments must be an array' using errcode = '22023';
  end if;
  select full_name into caller_name
  from public.profiles where id = caller;
  select * into t
  from public.tasks
  where id = p_task_id and deleted_at is null
  for update;
  if not found then raise exception 'Task not found'; end if;
  if t.archived_at is not null or t.status not in ('todo','in_progress','changes_requested') then
    raise exception 'This task is no longer open for submission' using errcode = '22023';
  end if;
  if coalesce(t.assigned_to, t.recommendation_lead_id) is distinct from caller then
    raise exception 'Only the assignee or task lead may submit this work'
      using errcode = '42501';
  end if;
  if public.auth_role(caller) is null or public.auth_role(caller)='admin' then
    raise exception 'Operational account required' using errcode='42501';
  end if;
  if exists(select 1 from public.projects where id=t.linked_project_id and project_lead_id is not null) then
    resolved_reviewer:=eflow_project.reviewer(t.id,caller);
  else
  if t.review_route_mode='organization_default' then
    select o.head_user_id into resolved_reviewer from public.organizations o
      where o.id=t.org_id and public.is_office_output_reviewer(o.id,o.head_user_id);
  else
    select p.id into resolved_reviewer from public.profiles p
      where p.id in (t.reviewer_id,t.backup_reviewer_id) and p.is_active and p.role<>'admin'
        and p.id<>caller and p.id is distinct from t.assigned_to
      order by (p.id=t.reviewer_id) desc limit 1;
  end if;
  end if;
  if resolved_reviewer is null then raise exception 'Assign an eligible reviewer before submitting' using errcode='22023'; end if;
  -- Starting and submitting share the task lock and transaction. A contributor
  -- starting work or a delayed client render cannot race a second start RPC.
  if not coalesce(eflow_r3.eligible(caller),false) then
    raise exception 'Your current work access could not be verified' using errcode='42501';
  end if;
  if t.status <> 'in_progress' then
    perform public.transition_task_status(p_task_id,'in_progress',null,'Work submitted by task lead');
  end if;
  submission_id := case
    when coalesce(p_submission ->> 'id', '') ~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
      then (p_submission ->> 'id')::uuid
    else gen_random_uuid()
  end;
  select coalesce(max(version), 0) + 1 into submission_version
  from public.task_submissions where task_id = p_task_id;
  insert into public.task_submissions (
    id, task_id, version, submitter_id, submitter_name, note
  ) values (
    submission_id,
    p_task_id,
    submission_version,
    caller,
    coalesce(caller_name, 'User'),
    completion_note
  );
  for attachment in
    select value from jsonb_array_elements(
      coalesce(p_submission -> 'attachments', '[]'::jsonb)
    )
  loop
    insert into public.task_attachments (
      task_id,
      submission_id,
      uploaded_by,
      uploader_name,
      file_name,
      file_path,
      file_size,
      mime_type
    ) values (
      p_task_id,
      submission_id,
      caller,
      coalesce(caller_name, 'User'),
      coalesce(attachment ->> 'fileName', 'Attachment'),
      attachment ->> 'filePath',
      case
        when coalesce(attachment ->> 'fileSize', '') ~ '^\d+$'
          then (attachment ->> 'fileSize')::bigint
        else 0
      end,
      coalesce(attachment ->> 'mimeType', '')
    );
  end loop;
  normalized_submission := jsonb_build_object(
    'id', submission_id::text,
    'version', submission_version,
    'note', completion_note,
    'submitterId', caller::text,
    'submitterName', coalesce(caller_name, 'User'),
    'submittedAt', floor(extract(epoch from clock_timestamp()) * 1000)::bigint,
    'attachments', coalesce(p_submission -> 'attachments', '[]'::jsonb)
  );
  perform set_config('eflow.allow_status_write', 'on', true);
  update public.tasks
  set
    reviewer_id = resolved_reviewer,
    latest_submission = normalized_submission,
    feedback = null,
    percent_complete = 100,
    status = 'for_review',
    last_activity_at = now()
  where id = p_task_id
  returning * into t;
  perform set_config('eflow.allow_status_write', 'off', true);
  insert into public.task_status_history (
    task_id, from_status, to_status, actor_id, actor_name, note
  ) values (
    p_task_id, 'in_progress', 'for_review', caller,
    coalesce(caller_name, 'User'), completion_note
  );
  insert into public.task_activities (
    task_id, type, content, actor_id, actor_name
  ) values (
    p_task_id, 'for_review', completion_note, caller,
    coalesce(caller_name, 'User')
  );
  insert into public.audit_events (
    actor_id, actor_name, entity_type, entity_id, action,
    reason, before_data, after_data, org_id
  ) values (
    caller, coalesce(caller_name, 'User'), 'task', p_task_id::text,
    'task.transition.for_review', completion_note,
    jsonb_build_object('status', 'in_progress'),
    jsonb_build_object(
      'status', 'for_review',
      'submissionId', submission_id,
      'submissionVersion', submission_version,
      'reviewerId', resolved_reviewer
    ),
    t.org_id
  );
  if resolved_reviewer <> caller then
    insert into public.notifications (
      user_id, type, title, message, task_id, task_title,
      actor_id, actor_name, status_from, status_to, reason
    ) values (
      resolved_reviewer, 'approval_needed', 'Task ready for review',
      coalesce(caller_name, 'Someone') || ' submitted "' || t.title || '" for review.',
      p_task_id, t.title, caller, coalesce(caller_name, 'User'),
      'in_progress', 'for_review', completion_note
    );
  end if;
  return t;
end;
$function$

CREATE OR REPLACE FUNCTION public.decide_task_review(p_task_id uuid, p_approve boolean, p_feedback text DEFAULT NULL::text, p_audit_hash text DEFAULT NULL::text)
 RETURNS tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

declare

  caller uuid := auth.uid();

  caller_role text;

  caller_name text;

  task_row public.tasks;

  submission public.task_submissions;

  next_status text;

  decision_hash text;

  recipient_id uuid;

  office_finalization boolean;

begin /* NW5.2 shared writer lock */ perform eflow_r7.lock_impact(p_task_id); /* NW4.2 completion serialization */ perform eflow_r7.lock_completion(p_task_id);

  if caller is null then

    raise exception 'Not authenticated' using errcode = '42501';

  end if;



  if not p_approve and coalesce(btrim(p_feedback), '') = '' then

    raise exception 'Feedback is required when requesting changes'

      using errcode = '22023';

  end if;



  select role::text, full_name

    into caller_role, caller_name

  from public.profiles

  where id = caller and is_active;



  select *

    into task_row

  from public.tasks

  where id = p_task_id

    and deleted_at is null

  for update;



  if not found then

    raise exception 'Task not found' using errcode = 'P0002';

  end if;



  if task_row.status <> 'for_review' then

    raise exception 'Task is not awaiting review' using errcode = '22023';

  end if;



  select *

    into submission

  from public.task_submissions

  where task_id = p_task_id

  order by version desc

  limit 1

  for update;



  if not found then

    raise exception 'No review submission exists' using errcode = '22023';

  end if;



  if exists(select 1 from public.projects where id=task_row.linked_project_id and project_lead_id is not null) and (caller is distinct from eflow_project.reviewer(task_row.id,submission.submitter_id) or caller=submission.submitter_id) then raise exception 'Only the current independent project reviewer may decide this task' using errcode='42501';end if;
  office_finalization := task_row.review_route_mode='organization_default'

    and task_row.reviewer_id=caller and public.is_office_output_reviewer(task_row.org_id,caller);

  if caller_role is null or caller_role='admin' then raise exception 'Operational account required' using errcode='42501'; end if;

  if submission.submitter_id = caller and not coalesce(office_finalization,false) then

    raise exception 'You cannot review your own submission' using errcode = '42501';

  end if;



  if not (

    task_row.reviewer_id = caller

    or task_row.backup_reviewer_id = caller

  ) then

    raise exception 'Only the assigned reviewer may decide this submission'

      using errcode = '42501';

  end if;



  next_status := case when p_approve then 'completed' else 'changes_requested' end;

  decision_hash := case when p_approve then encode(

    extensions.digest(

      p_task_id::text || ':' || submission.id::text || ':' || caller::text || ':' ||

      clock_timestamp()::text,

      'sha256'

    ),

    'hex'

  ) else null end;



  perform set_config('eflow.allow_status_write', 'on', true);

  perform set_config('eflow.review_decision_authorized', 'on', true);



  update public.tasks

  set

    status = next_status,

    percent_complete = case when p_approve then 100 else 99 end,

    feedback = nullif(btrim(p_feedback), ''),

    rejection_note = case

      when p_approve then rejection_note

      else nullif(btrim(p_feedback), '')

    end,

    rejected_at = case when p_approve then rejected_at else now() end,

    audit_hash = coalesce(decision_hash, audit_hash),

    last_activity_at = now()

  where id = p_task_id

  returning * into task_row;



  perform set_config('eflow.review_decision_authorized', 'off', true);

  perform set_config('eflow.allow_status_write', 'off', true);



  update public.task_submissions

  set

    status = case when p_approve then 'approved' else 'changes_requested' end,

    decided_by = caller,

    decided_by_name = coalesce(caller_name, 'Reviewer'),

    decision_feedback = nullif(btrim(p_feedback), ''),

    decided_at = now()

  where id = submission.id;



  insert into public.task_status_history (

    task_id, from_status, to_status, actor_id, actor_name, note

  ) values (

    p_task_id, 'for_review', next_status, caller,

    coalesce(caller_name, 'Reviewer'), nullif(btrim(p_feedback), '')

  );



  insert into public.task_activities (

    task_id, type, content, actor_id, actor_name

  ) values (

    p_task_id, next_status,

    coalesce(

      nullif(btrim(p_feedback), ''),

      case when p_approve then 'Review approved' else 'Changes requested' end

    ),

    caller, coalesce(caller_name, 'Reviewer')

  );



  insert into public.audit_events (

    actor_id, actor_name, entity_type, entity_id, action,

    reason, before_data, after_data, org_id

  ) values (

    caller, coalesce(caller_name, 'Reviewer'), 'task', p_task_id::text,

    'task.transition.' || next_status, nullif(btrim(p_feedback), ''),

    jsonb_build_object('status', 'for_review', 'submissionId', submission.id),

    jsonb_build_object('status', next_status, 'auditHash', decision_hash,

      'performedBy',submission.submitter_id,'finalizedBy',caller,'officeId',task_row.org_id,

      'authority',case when office_finalization then 'Office Head' else 'Assigned reviewer' end,

      'selfFinalization',submission.submitter_id=caller),

    task_row.org_id

  );



  for recipient_id in

    select distinct recipient.user_id

    from unnest(array[

      task_row.assigned_to,

      submission.submitter_id,

      task_row.recommendation_lead_id

    ]) as recipient(user_id)

    where recipient.user_id is not null

      and recipient.user_id <> caller

  loop

    insert into public.notifications (

      user_id, type, title, message, task_id, task_title,

      actor_id, actor_name, status_from, status_to, reason

    ) values (

      recipient_id,

      case when p_approve then 'completed' else 'status_change' end,

      case when p_approve then 'Task approved' else 'Changes requested' end,

      case

        when p_approve then 'Your work on "' || task_row.title || '" was approved.'

        else 'Changes were requested for "' || task_row.title || '".'

      end,

      p_task_id, task_row.title, caller, coalesce(caller_name, 'Reviewer'),

      'for_review', next_status, coalesce(nullif(btrim(p_feedback), ''), '')

    );

  end loop;



  return task_row;

end;

$function$

CREATE OR REPLACE FUNCTION public.submit_petty_cash_liquidation(p_request_id uuid, p_declared_spent numeric, p_note text, p_receipts jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller uuid := auth.uid();
  request public.petty_cash_requests;
  budget public.department_fiscal_budgets;
  item jsonb;
  receipt_total numeric := 0;
  liquidation_id uuid;
  next_version int;
  liquidation_status text;
begin /* NW5.2 shared writer lock */ perform eflow_r7.lock_impact((select task_id from public.petty_cash_requests where id=p_request_id));
  select * into request from public.petty_cash_requests where id = p_request_id for update;
  if not found then raise exception 'Petty-cash request not found' using errcode = 'P0002'; end if;
  if request.requester_id <> caller and request.cash_recipient_id <> caller then raise exception 'Only the cash recipient can submit this liquidation' using errcode = '42501'; end if;
  if request.status not in ('released', 'changes_requested', 'overdue_liquidation') then raise exception 'All scheduled cash must be released before liquidation' using errcode = '22023'; end if;
  if p_declared_spent < 0 or p_declared_spent > request.released_amount then raise exception 'Actual spending cannot exceed the amount released' using errcode = '22023'; end if;
  if nullif(btrim(p_note), '') is null then raise exception 'Add a liquidation note' using errcode = '22023'; end if;
  if jsonb_typeof(coalesce(p_receipts, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_receipts, '[]'::jsonb)) = 0 then raise exception 'Attach at least one receipt' using errcode = '22023'; end if;
  select * into budget from public.department_fiscal_budgets where id = request.fiscal_budget_id;
  for item in select value from jsonb_array_elements(p_receipts) loop
    if nullif(btrim(item ->> 'vendor'), '') is null or nullif(btrim(item ->> 'description'), '') is null
       or nullif(btrim(item ->> 'filePath'), '') is null or nullif(item ->> 'receiptDate', '') is null then
      raise exception 'Every receipt needs vendor, date, description, amount, and attachment' using errcode = '22023';
    end if;
    -- Per-receipt petty cash threshold check removed.
    receipt_total := receipt_total + coalesce((item ->> 'amount')::numeric, 0);
  end loop;
  if abs(receipt_total - p_declared_spent) > 0.009 then raise exception 'Receipt amounts must equal the declared amount spent' using errcode = '22023'; end if;
  select coalesce(max(version), 0) + 1 into next_version from public.petty_cash_liquidations where request_id = request.id;
  liquidation_status := case when request.task_leader_id = caller then 'pending_department_settlement' else 'pending_leader_review' end;
  insert into public.petty_cash_liquidations(request_id, version, declared_spent, returned_amount, note, status, submitted_by)
  values (request.id, next_version, p_declared_spent, request.released_amount - p_declared_spent, btrim(p_note), liquidation_status, caller)
  returning id into liquidation_id;
  for item in select value from jsonb_array_elements(p_receipts) loop
    insert into public.petty_cash_receipts(
      liquidation_id, vendor, receipt_number, receipt_date, description, amount,
      file_name, file_path, mime_type, file_size, override_reason, created_by
    ) values (
      liquidation_id, btrim(item ->> 'vendor'), nullif(btrim(item ->> 'receiptNumber'), ''),
      (item ->> 'receiptDate')::date, btrim(item ->> 'description'), (item ->> 'amount')::numeric,
      item ->> 'fileName', item ->> 'filePath', coalesce(nullif(item ->> 'mimeType', ''), 'application/octet-stream'),
      coalesce((item ->> 'fileSize')::bigint, 0), nullif(btrim(item ->> 'overrideReason'), ''), caller
    );
  end loop;
  update public.petty_cash_requests set status = case when liquidation_status = 'pending_leader_review' then 'pending_leader_liquidation_review' else 'pending_department_settlement' end, updated_at = now() where id = request.id;
  if liquidation_status = 'pending_leader_review' then
    insert into public.notifications(user_id, type, title, message, task_id, actor_id, actor_name, financial_record_id, financial_record_type)
    select request.task_leader_id, 'petty_cash_liquidation_leader_review', 'Expense liquidation needs your review',
      coalesce(profile.full_name, 'A team member') || ' submitted receipts totaling ' || to_char(p_declared_spent, 'FM999G999G999G990D00') || '.',
      request.task_id, caller, coalesce(profile.full_name, ''), liquidation_id, 'petty_cash_liquidation' from public.profiles profile where profile.id = caller;
  else
    insert into public.notifications(user_id, type, title, message, task_id, actor_id, actor_name, financial_record_id, financial_record_type)
    select approver_id, 'petty_cash_liquidation_department_review', 'Expense liquidation ready for settlement',
      coalesce(profile.full_name, 'A Task Leader') || ' submitted receipts totaling ' || to_char(p_declared_spent, 'FM999G999G999G990D00') || '.',
      request.task_id, caller, coalesce(profile.full_name, ''), liquidation_id, 'petty_cash_liquidation'
    from public.organization_approver_ids(request.org_id) approver_id left join public.profiles profile on profile.id = caller
    where approver_id <> caller;
  end if;
  return liquidation_id;
end;
$function$

CREATE OR REPLACE FUNCTION eflow_r7.operation_capabilities(p_root uuid, p_node uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$

declare

 r jsonb := eflow_r7.root(p_root);

 n eflow_r7.nodes;

 actions text[] := case when p_node is null then

  array['manage_contributors','appoint_lead','create_child','order_children'] else

  array['manage_contributors','appoint_lead','create_child','edit_details','move','order_children','delete','execute','submit','review'] end;

 action text;

 reason text;

 common_reason text;

 result jsonb := '{}';

 manager boolean;

 untouched boolean;

 descendants_complete boolean;

 ordered_ready boolean;

 node_depth integer;

begin

 -- Do not disclose row state through the private projector to an unavailable

 -- actor/scope. Snapshot retains its existing read exception.

 if r is null or auth.uid() is null or not coalesce(eflow_r7.read_root(p_root),false) then

  common_reason := 'access_unavailable';

 elsif not coalesce(eflow_r3.eligible(auth.uid()),false) then

  common_reason := 'read_only';

 elsif not coalesce((r->>'open')::boolean,false) then

  common_reason := 'lifecycle_blocked';

 end if;

 if p_node is not null then

  select * into n from eflow_r7.nodes where id=p_node and task_id=p_root;

  if not found then common_reason := 'access_unavailable'; end if;

 end if;

 if common_reason is null then

  manager := coalesce(eflow_r7.manage(p_root,p_node),false);

  if p_node is not null then

   with recursive below as (

    select * from eflow_r7.nodes where id=p_node and task_id=p_root

    union all select c.* from eflow_r7.nodes c join below b on c.parent_subtask_id=b.id where c.task_id=p_root

   ) select not exists(select 1 from below where status<>'todo' or percent_complete<>0),

    not exists(select 1 from below where id<>p_node and status<>'completed')

    into untouched,descendants_complete;

   with recursive above as (

    select id,parent_subtask_id,1 depth from eflow_r7.nodes where id=p_node and task_id=p_root

    union all select c.id,c.parent_subtask_id,a.depth+1 from eflow_r7.nodes c join above a on c.id=a.parent_subtask_id where c.task_id=p_root and a.depth<8

   ) select max(depth) into node_depth from above;

   ordered_ready := n.is_standalone or not exists(select 1 from eflow_r7.nodes c

    where c.task_id=p_root and c.parent_subtask_id is not distinct from n.parent_subtask_id

    and c.sibling_order<n.sibling_order and not c.is_standalone and c.status<>'completed');
   if r->>'kind'='office' and exists(
     select 1 from public.subtasks s where s.id=p_node and s.task_id=p_root and s.dependency_ids is not null
   ) then
    ordered_ready := eflow_r7.subtask_dependencies_ready(p_root,(select s.dependency_ids from public.subtasks s where s.id=p_node));
   end if;

  end if;

 end if;

 foreach action in array actions loop

  reason := common_reason;

  if reason is null then

   if p_node is not null and action in ('appoint_lead','manage_contributors')
     and eflow_publication.subtask_staffing_locked(p_root)
     and (r->>'lead')::uuid is distinct from auth.uid()
     and (action='appoint_lead' or n.lead_id is distinct from auth.uid()) then reason:='active_subtask_staffing_locked';
   elsif action='appoint_lead' then

    if not coalesce(case when p_node is null then (eflow_r7.head(p_root) or (r->>'kind'='office' and eflow_publication.planning_lead((r->>'project')::uuid,(r->>'office')::uuid)))

     else eflow_publication.manage_plan(p_root,p_node,true) end,false) then reason := 'appointment_denied';

    elsif p_node is not null and n.status='completed' then reason := 'lifecycle_blocked'; end if;

   elsif action in ('execute','submit') and r->>'kind'='office' and exists (
    select 1 from public.projects where id=(r->>'project')::uuid and status in ('planning','on_hold')
   ) then
    select case when status='on_hold' then 'project_on_hold' else 'lifecycle_blocked' end into reason
     from public.projects where id=(r->>'project')::uuid;
   elsif action in ('execute','submit') then
    if not coalesce(manager,false) and (action='submit' or not coalesce(eflow_r7.node_work(p_node,auth.uid()),false)) then reason:='branch_denied';
    elsif n.status='completed' or r->>'kind'='office' and r->>'status' not in ('todo','in_progress','changes_requested') then reason:='lifecycle_blocked';
    elsif not ordered_ready or action='submit' and not descendants_complete then reason:='lifecycle_blocked';end if;
   elsif action='review' then
    reason:='lifecycle_blocked'; -- Subitems complete directly; final task retains its review.
   elsif action = 'manage_contributors' and p_node is null and coalesce(eflow_publication.root_contributor_change_locked(p_root),false) then reason := 'active_staffing_locked'; elsif not eflow_publication.manage_plan(p_root,p_node) then reason := 'branch_denied';

   elsif action='manage_contributors' then

    if p_node is null and r->>'kind'<>'office' then reason := 'read_only';

    elsif p_node is null and r->>'lead' is null or p_node is not null and (n.lead_id is null or n.status='completed') then reason := 'lifecycle_blocked'; end if;

   elsif action='create_child' then

    if p_node is not null and (n.status<>'todo' or n.percent_complete<>0 or node_depth>=8) then reason := 'lifecycle_blocked'; end if;

   elsif action='order_children' then

    -- This is parent:p_node, including parent:null for root direct children.

    if exists(select 1 from eflow_r7.nodes c where c.task_id=p_root

     and c.parent_subtask_id is not distinct from p_node and (c.status<>'todo' or c.percent_complete<>0)) then reason := 'lifecycle_blocked'; end if;

   elsif action='edit_details' and r->>'kind'='office' then
    if not coalesce((eflow_work_edit.state(p_root,p_node)->>'details')::boolean,false) then reason:='lifecycle_blocked';end if;
   elsif action in ('edit_details','move','delete') then

    if not untouched then reason := 'lifecycle_blocked';

    elsif action='delete' and r->>'kind'='office' and exists(

     with recursive below as (select id from eflow_r7.nodes where id=p_node and task_id=p_root

      union all select c.id from eflow_r7.nodes c join below b on c.parent_subtask_id=b.id where c.task_id=p_root)

     select 1 from below b where

      exists(select 1 from public.subtask_progress_updates where subtask_id=b.id) or

      exists(select 1 from public.subtask_submissions where subtask_id=b.id) or

      exists(select 1 from public.work_budget_allocations where subtask_id=b.id) or

      exists(select 1 from public.petty_cash_requests where subtask_id=b.id) or

      exists(select 1 from public.budget_ledger_entries where subtask_id=b.id)

    ) then reason := 'history_blocked'; end if;

   end if;

  end if;

  if reason is null and p_node is not null and action in ('execute','submit') and
   not (case when r->>'kind'='office' then eflow_m7.node_activated(p_root,p_node)
             else eflow_m7.personal_node_activated(p_root,p_node) end)
  then reason := 'lifecycle_blocked'; end if;

  /* NW5.1 history capability */

  if reason is null and action in ('create_child','order_children','move','delete') then

   if not (eflow_r7.operation_impact(p_root,case action when 'create_child' then 'create' when 'order_children' then 'order' else action end,

    case when action in ('create_child','order_children') then jsonb_build_object('parent',p_node) else jsonb_build_object('id',p_node,'parent',n.parent_subtask_id) end)->>'allowed')::boolean then reason:='history_blocked';end if;

  end if;

 result := result || jsonb_build_object(action,jsonb_build_object('allowed',reason is null,'reason_code',reason));

 end loop;

 return result;

end $function$

CREATE OR REPLACE FUNCTION public.guard_financial_work_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status = 'completed' and old.status is distinct from 'completed' and exists (
    select 1 from public.petty_cash_requests request
    where request.task_id = new.task_id
      and request.subtask_id = new.id
      and request.status not in ('settled', 'rejected', 'cancelled')
  ) then raise exception 'Settle all released or reserved cash before approving this funded subtask' using errcode = '22023'; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_task_financial_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
 request public.petty_cash_requests;
 liquidation public.petty_cash_liquidations;
 approver uuid;
begin
 if new.status is distinct from 'completed' or old.status = 'completed' then return new; end if;
 for request in
  select r.* from public.petty_cash_requests r where r.task_id=new.id
    and r.status not in ('settled','rejected','cancelled') order by r.id
 loop
  if request.status='pending_department_settlement' then
   select * into liquidation from public.petty_cash_liquidations l
    where l.request_id=request.id order by l.version desc,l.id desc limit 1;
   if liquidation.status='pending_department_settlement' and
      (request.liquidation_due_at is null or liquidation.submitted_at<=request.liquidation_due_at
       or liquidation.department_decided_at is not null) then
    approver:=eflow_finance_review.staffing_escalation_approver(liquidation,request);
    if approver is not null then
     perform eflow_finance_review.lock_authority(request.org_id,array[approver]);
     if eflow_finance_review.staffing_escalation_approver(liquidation,request)=approver then
      continue;
     end if;
    end if;
   end if;
  end if;
  raise exception 'Settle all task and subtask cash before approving this task' using errcode='22023';
 end loop;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION eflow_project.release_funding(p_project uuid, p_source uuid, p_amount numeric, p_reason text, p_key uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.projects;f eflow_project.funding;used numeric;b uuid;receipt eflow_project.commands;payload jsonb;
begin
 select * into p from public.projects where id=p_project for update;
 if p.id is null or auth.uid() is null or not public.phase2_is_office_head(auth.uid(),p.org_id) then raise exception 'Only the appointed Head may release unused project funding' using errcode='42501';end if;
 payload:=jsonb_build_object('project',p_project,'source',p_source,'amount',p_amount,'reason',p_reason);
 select * into receipt from eflow_project.commands where actor_id=auth.uid() and request_id=p_key;
 if found then if receipt.payload<>payload then raise exception 'Release request terms changed' using errcode='23514';end if;return;end if;
 select * into f from eflow_project.funding where id=p_source and project_id=p.id for update;
 if f.id is null or p_amount is null or p_amount<=0 or round(p_amount,2)<>p_amount or btrim(coalesce(p_reason,''))='' or p_key is null then raise exception 'Choose a project funding source, positive amount and release reason' using errcode='23514';end if;
 select coalesce(sum(l.amount),0) into used from public.work_budget_allocation_lines l join public.work_budget_allocations a on a.id=l.allocation_id where l.project_funding_id=f.id and a.status='approved' and a.subtask_id is null;
 if p_amount>f.amount-used then raise exception 'Only % remains unallocated; release the unused task allocations first',f.amount-used using errcode='23514';end if;
 select fiscal_budget_id into b from public.budget_commitments where id=f.commitment_id for update;
 update eflow_project.funding set amount=amount-p_amount where id=f.id;
 update public.budget_commitments set amount=amount-p_amount where id=f.commitment_id;
 insert into public.budget_ledger_entries(fiscal_budget_id,org_id,commitment_id,entry_type,amount,description,actor_id,reason,metadata) values(b,p.org_id,f.commitment_id,'proposal_released',p_amount,'Unused project funding released',auth.uid(),p_reason,jsonb_build_object('projectId',p.id,'sourceId',p_source));
 insert into eflow_project.commands values(auth.uid(),p_key,payload,'{}');
end $function$

CREATE OR REPLACE FUNCTION eflow_project.release_task_line(p_line uuid, p_amount numeric, p_reason text, p_key uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare l public.work_budget_allocation_lines;a public.work_budget_allocations;t public.tasks;p public.projects;available numeric;remaining numeric;payload jsonb;receipt eflow_project.commands;
begin
 select wa.* into a from public.work_budget_allocations wa join public.work_budget_allocation_lines line on line.allocation_id=wa.id where line.id=p_line;
 perform eflow_r7.lock_impact(a.task_id);
 select * into t from public.tasks where id=a.task_id;select * into p from public.projects where id=t.linked_project_id for update;
 if p.id is null or auth.uid() is null or not (eflow_project.lead(p.id,auth.uid()) or public.phase2_is_office_head(auth.uid(),p.org_id)) then raise exception 'Current project lead or Head required' using errcode='42501';end if;
 payload:=jsonb_build_object('line',p_line,'amount',p_amount,'reason',p_reason);
 select * into receipt from eflow_project.commands where actor_id=auth.uid() and request_id=p_key;
 if found then if receipt.payload<>payload then raise exception 'Release request terms changed' using errcode='23514';end if;return;end if;
 select * into a from public.work_budget_allocations where id=a.id for update;
 select * into l from public.work_budget_allocation_lines where id=p_line for update;
 if l.project_funding_id is null or a.subtask_id is not null or a.status<>'approved' or p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) or p_key is null or btrim(coalesce(p_reason,''))='' then raise exception 'Choose an approved task source, positive amount and release reason' using errcode='23514';end if;
 available:=public.task_budget_line_available(l.id,null);
 if p_amount>available then raise exception 'Only % is unused; cash obligations and subtask allocations remain protected',available using errcode='23514';end if;
 update public.work_budget_allocation_lines set amount=amount-p_amount,unit_cost=greatest(unit_cost-p_amount,0) where id=l.id;
 select sum(amount) into remaining from public.work_budget_allocation_lines where allocation_id=a.id;
 if remaining=0 then update public.work_budget_allocations set status='cancelled',decision_reason=p_reason,updated_at=now() where id=a.id;else update public.work_budget_allocations set amount=remaining,decision_reason=p_reason,updated_at=now() where id=a.id;end if;
 insert into public.audit_events(actor_id,entity_type,entity_id,action,org_id,reason,before_data,after_data) values(auth.uid(),'task',t.id::text,'project.task_unused_funding_released',p.org_id,p_reason,jsonb_build_object('line',l.id,'amount',l.amount),jsonb_build_object('amount',l.amount-p_amount));
 insert into eflow_project.commands values(auth.uid(),p_key,payload,'{}');
end $function$

CREATE OR REPLACE FUNCTION public.approve_liquidation_staffing_escalation(p_liquidation_id uuid, p_version integer, p_fingerprint text, p_reason text, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  l public.petty_cash_liquidations; r public.petty_cash_requests;
  prior eflow_finance_review.staffing_escalation_approvals;
  caller uuid:=auth.uid();
  head_fallback boolean;
begin
  if caller is null then raise exception 'Current Office Head access required' using errcode='42501'; end if;
  if p_version is null or p_idempotency_key is null or p_fingerprint is null
     or nullif(btrim(p_reason),'') is null or length(p_reason)>2000 then
    raise exception 'Enter a reason and verify the current package' using errcode='22023';
  end if;
  perform eflow_r7.lock_impact((select c.task_id from public.petty_cash_liquidations x
    join public.petty_cash_requests c on c.id=x.request_id where x.id=p_liquidation_id));
  select * into l from public.petty_cash_liquidations where id=p_liquidation_id for update;
  select * into r from public.petty_cash_requests where id=l.request_id for update;
  if r.id is null then raise exception 'Liquidation unavailable' using errcode='42501'; end if;
  -- Serialize the no-officer check with changes to Office staffing.
  perform 1 from public.organizations where id=r.org_id for update;
  perform 1 from public.profiles where org_id=r.org_id order by id for share;
  head_fallback:=coalesce(eflow_finance_review.head_can_post_settlement(l,r,caller),false);
  select * into prior from eflow_finance_review.staffing_escalation_approvals where command_id=p_idempotency_key;
  if found then
    if (prior.liquidation_id,prior.version,prior.head_id,prior.fingerprint,prior.reason)
      is distinct from (l.id,p_version,caller,p_fingerprint,btrim(p_reason)) then
      raise exception 'This approval identity was already used' using errcode='22023';
    end if;
    if head_fallback then
      perform eflow_finance_review.settle_accounting_liquidation(l.id,true,prior.reason);
    end if;
    return prior.command_id;
  end if;
  if not head_fallback and not coalesce(eflow_finance_review.staffing_escalation_head(l,r,caller),false) then
    raise exception 'Only the authorized Office Head may approve this escalation' using errcode='42501';
  end if;
  if l.version<>p_version or l.status<>'pending_department_settlement' or r.status<>'pending_department_settlement'
    or p_fingerprint<>eflow_finance_review.fingerprint(l,r) then
    raise exception 'The receipt package changed. Review the current version.' using errcode='22023';
  end if;
  if not head_fallback and exists(select 1 from public.profiles p where p.org_id=r.org_id
     and eflow_finance_review.eligible_reviewer(r,p.id)) then
    raise exception 'Send this package to the available independent reviewer' using errcode='42501';
  end if;
  select * into prior from eflow_finance_review.staffing_escalation_approvals
  where liquidation_id=l.id and version=l.version and fingerprint=p_fingerprint and head_id=caller;
  if found then
    if not head_fallback then raise exception 'The Head already approved this escalation' using errcode='22023'; end if;
    perform eflow_finance_review.settle_accounting_liquidation(l.id,true,btrim(p_reason));
    return prior.command_id;
  end if;
  insert into eflow_finance_review.staffing_escalation_approvals
    (command_id,liquidation_id,version,head_id,fingerprint,reason)
  values (p_idempotency_key,l.id,l.version,caller,p_fingerprint,btrim(p_reason));
  if head_fallback then
    perform eflow_finance_review.settle_accounting_liquidation(l.id,true,btrim(p_reason));
    return p_idempotency_key;
  end if;
  insert into public.notifications (user_id,type,title,message,reason,financial_record_id,financial_record_type,task_id,actor_id)
  values (r.cash_recipient_id,'petty_cash_liquidation_decision','Head approved settlement review',
    'A separate eligible Accounting Officer must settle and post.',btrim(p_reason),l.id,'petty_cash_liquidation',r.task_id,caller);
  return p_idempotency_key;
end $function$

CREATE OR REPLACE FUNCTION eflow_finance_review.settle_accounting_liquidation(p_liquidation_id uuid, p_approve boolean, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare caller uuid := auth.uid(); liquidation public.petty_cash_liquidations; request public.petty_cash_requests; head_fallback boolean;
begin
  perform eflow_r7.lock_impact((select c.task_id from public.petty_cash_liquidations l
    join public.petty_cash_requests c on c.id=l.request_id where l.id=p_liquidation_id));
  select * into liquidation from public.petty_cash_liquidations where id = p_liquidation_id for update;
  if not found then raise exception 'Liquidation not found' using errcode = 'P0002'; end if;
  select * into request from public.petty_cash_requests where id = liquidation.request_id for update;
  head_fallback := p_approve is true
    and eflow_finance_review.head_can_post_settlement(liquidation,request,caller)
    and exists (select 1 from eflow_finance_review.staffing_escalation_approvals a
      where a.liquidation_id=liquidation.id and a.version=liquidation.version and a.head_id=caller
        and a.fingerprint=eflow_finance_review.fingerprint(liquidation,request));
  if not head_fallback and not (public.is_department_accounting_staff(request.org_id,caller) and public.has_permission(caller,'accounting.settle_liquidation')) then
    raise exception 'Only authorized Accounting Staff can settle this liquidation' using errcode = '42501';
  end if;
  if caller in (request.cash_recipient_id, request.requester_id) then raise exception 'You cannot settle your own liquidation' using errcode = '42501'; end if;
  if not head_fallback and caller = liquidation.leader_decided_by then raise exception 'Leader review and settlement must be performed by different people' using errcode = '42501'; end if;
  if liquidation.status <> 'pending_department_settlement' or request.status <> 'pending_department_settlement' then
    raise exception 'This liquidation is not awaiting accounting settlement' using errcode = '22023';
  end if;
  if not p_approve and nullif(btrim(p_reason), '') is null then raise exception 'Explain what must be corrected' using errcode = '22023'; end if;
  update public.petty_cash_liquidations set status = case when p_approve then 'approved' else 'changes_requested' end,
    decided_by = caller, decision_reason = nullif(btrim(p_reason), ''), decided_at = now()
  where id = liquidation.id;
  if p_approve then
    update public.petty_cash_requests set status = 'settled', actual_spent = liquidation.declared_spent,
      returned_amount = liquidation.returned_amount, settled_by = caller, settled_at = now(), updated_at = now()
    where id = request.id;
    insert into public.budget_ledger_entries(fiscal_budget_id, org_id, commitment_id, allocation_id, petty_cash_request_id, entry_type, amount, description, actor_id)
    values (request.fiscal_budget_id, request.org_id, request.commitment_id, request.allocation_id, request.id,
      'expense_posted', liquidation.declared_spent, 'Verified receipts posted as actual task spending', caller);
    if liquidation.returned_amount > 0 then
      insert into public.budget_ledger_entries(fiscal_budget_id, org_id, commitment_id, allocation_id, petty_cash_request_id, entry_type, amount, description, actor_id)
      values (request.fiscal_budget_id, request.org_id, request.commitment_id, request.allocation_id, request.id,
        'cash_returned', liquidation.returned_amount, 'Unused released cash returned to the department', caller);
    end if;
  else
    update public.petty_cash_requests set status = 'changes_requested', updated_at = now() where id = request.id;
  end if;
  insert into public.notifications(user_id, type, title, message, task_id, actor_id, actor_name, reason, financial_record_id, financial_record_type)
  select request.cash_recipient_id, 'petty_cash_liquidation_decision',
    case when p_approve then 'Expense liquidation settled' else 'Liquidation changes requested' end,
    case when p_approve then 'The receipts were verified and the balanced settlement journal was posted.' else 'Your liquidation needs corrections before settlement.' end,
    request.task_id, caller, coalesce(full_name, ''), coalesce(p_reason, ''), liquidation.id, 'petty_cash_liquidation'
  from public.profiles where id = caller;
end;
$function$

CREATE OR REPLACE FUNCTION eflow_m7.work_reviewer(p_root uuid, p_node uuid, p_author uuid, p_kind text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.tasks; n public.subtasks; chosen uuid;
 personal public.personal_tasks; child public.personal_subtasks;
begin
 if not coalesce(eflow_r3.eligible(p_author),false) then return null; end if;
 select * into personal from public.personal_tasks where id=p_root;
 if found then
  if p_node is null or not eflow_r7.member(personal.project_id,null,p_author) or personal.lead_id=p_author then return null; end if;
  select * into child from public.personal_subtasks where id=p_node and task_id=p_root;
  if not found then return null; end if;
  if child.lead_id=p_author and p_kind='completion' then chosen:=personal.lead_id;
  elsif child.lead_id is distinct from p_author and p_author=any(child.assigned_to_ids) then
   chosen:=case when eflow_r7.member(personal.project_id,null,child.lead_id) then child.lead_id else eflow_r7.reviewer(child.id,p_author) end;
  end if;
  if chosen is null or chosen=p_author or not eflow_r7.member(personal.project_id,null,chosen) then return null; end if;
  return chosen;
 end if;
 if not public.can_see_task(p_root,p_author) then return null; end if;
 select * into t from public.tasks where id=p_root;
 if p_node is null then
  if p_author=t.assigned_to or not coalesce(p_author=any(t.team_member_ids),false) then return null; end if;
  chosen:=t.assigned_to;
 else
  select * into n from public.subtasks where task_id=p_root and id=p_node;
  if n.id is null or p_author=t.assigned_to then return null; end if;
  if p_author=n.lead_id then
   if p_kind<>'completion' then return null; end if;
   chosen:=t.assigned_to;
  elsif coalesce(p_author=any(n.assigned_to_ids),false) then
   chosen:=eflow_r7.reviewer(n.id,p_author);
  end if;
 end if;
 if chosen is null or chosen=p_author or not eflow_r7.member(t.linked_project_id,t.org_id,chosen)
    or not public.can_see_task(t.id,chosen) then return null; end if;
 return chosen;
end $function$

CREATE OR REPLACE FUNCTION eflow_r7.complete_subitem(p_subtask_id uuid, p_completion jsonb)
 RETURNS subtasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 caller uuid:=auth.uid();root_id uuid;r jsonb;s public.subtasks;t public.tasks;
 v_request uuid;previous_status text;terms jsonb;receipt eflow_r7.receipts;name text;attachment jsonb;
 files jsonb:=coalesce(p_completion->'attachments','[]'::jsonb);note text:=btrim(coalesce(p_completion->>'note',''));
 index integer:=0;previous_flag text;
begin
 perform eflow_r3.actor();
 select task_id into root_id from public.subtasks where id=p_subtask_id;
 if root_id is null then raise exception 'Subitem unavailable' using errcode='42501';end if;
 r:=eflow_r7.root(root_id);
 if r is not null and not coalesce(eflow_r7.read_root(root_id),false) then raise exception 'Current work access required' using errcode='42501';end if;
 perform eflow_r7.lock_impact(root_id);
 perform 1 from public.projects where id=(r->>'project')::uuid for update;
 perform eflow_r7.lock_completion(root_id);
 select * into t from public.tasks where id=root_id and deleted_at is null for update;
 select * into s from public.subtasks where id=p_subtask_id and task_id=root_id for update;
 if t.id is null or s.id is null then raise exception 'Subitem unavailable' using errcode='42501';end if;

 if r is not null and (not eflow_m7.node_activated(root_id,p_subtask_id) or t.assigned_to is distinct from caller
    or (s.lead_id is distinct from caller and not exists(
     select 1 from eflow_m7.applying_work_proposal a join eflow_m7.work_proposals w on w.id=a.proposal_id
     where a.tx=txid_current() and w.id=(p_completion->>'id')::uuid and w.node_id=s.id
      and w.root_id=t.id and w.reviewer_id=caller and w.submitted_as_lead and w.kind='completion'
    ))) then raise exception 'Submit this subtask for the appointed Task Lead to review' using errcode='42501'; end if;
 previous_status:=s.status;
 v_request:=(p_completion->>'id')::uuid;
 if v_request is null or jsonb_typeof(files)<>'array' or jsonb_array_length(files)>10 or length(note)>3000
 or exists(select 1 from jsonb_object_keys(p_completion) k where k not in ('id','note','attachments')) then raise exception 'Invalid completion details' using errcode='22023';end if;
 terms:=jsonb_build_object('command','complete_subitem','payload',p_completion,'subtask',p_subtask_id);
 select * into receipt from eflow_r7.receipts q where q.actor_id=caller and q.request_id=v_request;
 -- Qualify the parameter/local name to avoid receipt/request column ambiguity below.
 if found then
  if receipt.root_id<>root_id or receipt.payload<>terms then raise exception 'Completion request terms changed' using errcode='22023';end if;
  return s;
 end if;
 r:=eflow_r7.root(root_id);
 if r is not null then
  if not coalesce((eflow_r7.operation_capabilities(root_id,p_subtask_id)->'submit'->>'allowed')::boolean,false) then raise exception 'Only a current subitem lead or task lead may complete this step; finish earlier and child steps first' using errcode='42501';end if;
 elsif not coalesce(public.can_manage_subtasks(root_id,caller) or s.assigned_to=caller or s.lead_id=caller,false) then raise exception 'Current task or subitem lead required' using errcode='42501';end if;
 if t.status not in ('todo','in_progress','changes_requested') or s.status='completed' then raise exception 'This work is closed or already completed' using errcode='22023';end if;
 if s.dependency_ids is null and not s.is_standalone and exists(select 1 from public.subtasks c where c.task_id=root_id and c.parent_subtask_id is not distinct from s.parent_subtask_id and c.sibling_order<s.sibling_order and not c.is_standalone and c.status<>'completed') then raise exception 'Complete earlier ordered steps first' using errcode='22023';end if;
 perform eflow_r7.require_completed_descendants(root_id,p_subtask_id);
 for attachment in select value from jsonb_array_elements(files) loop
  if jsonb_typeof(attachment)<>'object' or coalesce(attachment->>'filePath','') not like 'subtasks/'||p_subtask_id::text||'/'||v_request::text||'/%'
   or length(coalesce(attachment->>'fileName','')) not between 1 and 255 or coalesce((attachment->>'fileSize')::bigint,0) not between 1 and 26214400
   or not exists(select 1 from storage.objects o where o.bucket_id='task-attachments' and o.name=attachment->>'filePath' and o.owner_id=caller::text)
  then raise exception 'Completion attachment does not belong to this request' using errcode='42501';end if;
 end loop;
 select full_name into name from public.profiles where id=caller;
 insert into eflow_r7.mutations values(txid_current(),caller,root_id);
 previous_flag:=coalesce(current_setting('eflow.subtask_workflow_authorized',true),'off');
 perform set_config('eflow.subtask_workflow_authorized','on',true);
 update public.subtasks set status='completed',is_completed=true,percent_complete=100,completed_by=caller,completed_at=now(),reviewer_id=null,latest_submission_id=null where id=p_subtask_id returning * into s;
 perform set_config('eflow.subtask_workflow_authorized',previous_flag,true);
 -- Use existing update/evidence history; no review or approval record is created.
 insert into public.subtask_progress_updates(id,subtask_id,task_id,author_id,author_name,percent_complete,blocker_category,note,attachment_path,attachment_name)
 values(v_request,s.id,root_id,caller,coalesce(name,'User'),100,'None','Completed subitem.'||case when note='' then '' else E'\n'||note end,files->0->>'filePath',files->0->>'fileName');
 for attachment in select value from jsonb_array_elements(files) loop
  if index>0 then insert into public.subtask_progress_updates(subtask_id,task_id,author_id,author_name,percent_complete,blocker_category,note,attachment_path,attachment_name)
   values(s.id,root_id,caller,coalesce(name,'User'),100,'None','Additional completion attachment',attachment->>'filePath',attachment->>'fileName');end if;
  index:=index+1;
 end loop;
 insert into public.task_activities(task_id,type,content,actor_id,actor_name) values(root_id,'subtask_completed',coalesce(name,'User')||' completed subitem "'||s.title||'"',caller,coalesce(name,'User'));
 insert into public.audit_events(actor_id,actor_name,entity_type,entity_id,action,before_data,after_data,org_id)
 values(caller,coalesce(name,'User'),'subtask',s.id::text,case when exists(select 1 from eflow_m7.applying_work_proposal where tx=txid_current() and proposal_id=v_request)
  then 'subtask.completed_after_lead_review' else 'subtask.completed_directly' end,jsonb_build_object('status',previous_status),jsonb_build_object('status','completed','request',v_request),t.org_id);
 delete from eflow_r7.mutations where tx=txid_current() and actor=caller and eflow_r7.mutations.root_id=s.task_id;
 insert into eflow_r7.receipts values(caller,v_request,root_id,terms,to_jsonb(s));
 return s;
end $function$

CREATE OR REPLACE FUNCTION eflow_budget.submit_items(p_request uuid, p_spent numeric, p_note text, p_receipts jsonb, p_key uuid, p_refund_number text, p_refund_date date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.petty_cash_requests;li public.petty_cash_liquidations;rc jsonb;item jsonb;receipt_id uuid;source public.work_budget_allocation_lines;
  s public.office_budget_sections;total numeric;receipt_total numeric:=0;item_total numeric;pos integer;amt numeric;quantity numeric;payload jsonb;paths text[]:='{}';authorized record;
begin /* NW5.2 shared writer lock */ perform eflow_r7.lock_impact((select task_id from public.petty_cash_requests where id=p_request));
  select * into r from public.petty_cash_requests where id=p_request for update;
  if r.id is null or auth.uid() is null or (r.requester_id<>auth.uid() and r.cash_recipient_id<>auth.uid())
    or not exists(select 1 from public.profiles where id=auth.uid() and is_active and role not in ('admin','super_admin','viewer')) then raise exception 'Only the active cash recipient can submit purchased items' using errcode='42501';end if;
  if p_key is null then raise exception 'A liquidation idempotency key is required' using errcode='22023';end if;
  payload:=jsonb_build_object('spent',p_spent,'note',p_note,'receipts',p_receipts,'refundNumber',p_refund_number,'refundDate',p_refund_date);
  select * into li from public.petty_cash_liquidations where request_id=r.id and idempotency_key=p_key;
  if li.id is not null then
    if li.itemized_payload is distinct from payload then raise exception 'Liquidation key belongs to different receipt items' using errcode='22023';end if;return li.id;
  end if;
  if p_receipts is null or jsonb_typeof(p_receipts)<>'array' or jsonb_array_length(p_receipts) not between 1 and 100 or not eflow_budget.valid_money(p_spent,true) then raise exception 'Use a valid itemized receipt package' using errcode='22023';end if;
  for rc in select value from jsonb_array_elements(p_receipts) loop
    if not eflow_budget.valid_money((rc->>'amount')::numeric,true) or nullif(btrim(rc->>'filePath'),'') is null or (rc->>'filePath')=any(paths)
       or rc->'items' is null or jsonb_typeof(rc->'items')<>'array' or jsonb_array_length(rc->'items')>100 then raise exception 'Each receipt needs one unique evidence path and valid purchased items' using errcode='22023';end if;
    if left(rc->>'filePath',length(r.org_id::text||'/'||r.id::text||'/'))<>r.org_id::text||'/'||r.id::text||'/'
      or not exists(select 1 from storage.objects o where o.bucket_id='budget-receipts' and o.name=rc->>'filePath' and o.owner_id=auth.uid()::text) then
      raise exception 'Receipt evidence must be an uploaded file owned by this recipient in this cash request' using errcode='42501';end if;
    paths:=array_append(paths,rc->>'filePath');total:=0;
    for item in select value from jsonb_array_elements(rc->'items') loop
      amt:=(item->>'amount')::numeric;quantity:=(item->>'quantity')::numeric;
      if not eflow_budget.valid_money(amt) or quantity is null or quantity::text in ('NaN','Infinity','-Infinity') or quantity<=0 or quantity>9007199254740 or quantity<>round(quantity,3)
        or nullif(btrim(item->>'unit'),'') is null or nullif(btrim(item->>'particular'),'') is null or nullif(btrim(item->>'purpose'),'') is null then raise exception 'Each item needs quantity, unit, particulars, purpose and a positive line amount' using errcode='22023';end if;
      if not exists(select 1 from public.petty_cash_request_lines where request_id=r.id and allocation_line_id=(item->>'allocationLineId')::uuid) then raise exception 'Purchased item uses an unauthorized funding account' using errcode='42501';end if;
      total:=total+amt;
    end loop;
    if total is distinct from (rc->>'amount')::numeric then raise exception 'Item totals must equal each receipt total' using errcode='22023';end if;
    receipt_total:=receipt_total+total;
  end loop;
  if receipt_total is distinct from p_spent then raise exception 'Receipt totals must equal declared spending exactly' using errcode='22023';end if;
  for authorized in select * from eflow_budget.authorized_cash_lines(r.id) loop
    select coalesce(sum((it.value->>'amount')::numeric),0) into item_total from jsonb_array_elements(p_receipts) rc,
      lateral jsonb_array_elements(rc.value->'items') it where (it.value->>'allocationLineId')::uuid=authorized.allocation_line_id;
    if item_total>authorized.amount then raise exception 'Spending exceeds this account authorization; obtain reauthorization first' using errcode='22023';end if;
  end loop;
  -- The established command preserves release acknowledgment, receipt limits,
  -- refund, evidence guards, reviewer routing and immutable receipt history.
  li.id:=public.submit_accounting_cash_liquidation(p_request,p_spent,p_note,p_receipts,p_key,p_refund_number,p_refund_date);
  for rc in select value from jsonb_array_elements(p_receipts) loop
    select id into strict receipt_id from public.petty_cash_receipts where liquidation_id=li.id and file_path=rc->>'filePath';
    pos:=0;
    for item in select value from jsonb_array_elements(rc->'items') loop
      select * into source from public.work_budget_allocation_lines where id=(item->>'allocationLineId')::uuid;
      select * into s from public.office_budget_sections where id=source.budget_partition_id;
      insert into public.petty_cash_receipt_items(receipt_id,allocation_line_id,quantity,unit,particular,purpose,amount,position,account_name,account_label)
      values(receipt_id,source.id,(item->>'quantity')::numeric,btrim(item->>'unit'),btrim(item->>'particular'),btrim(item->>'purpose'),(item->>'amount')::numeric,pos,coalesce(s.name,source.category),s.account_code);
      pos:=pos+1;
    end loop;
  end loop;
  update public.petty_cash_liquidations set itemized_payload=payload where id=li.id;
  return li.id;
end $function$

CREATE OR REPLACE FUNCTION eflow_budget.pre_integrity_accounting_liquidation(p_request_id uuid, p_declared_spent numeric, p_note text, p_receipts jsonb, p_idempotency_key uuid, p_refund_receipt_number text DEFAULT NULL::text, p_refund_date date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare liquidation_id uuid; returned_value numeric;
begin
  select coalesce(released_amount, 0) - p_declared_spent into returned_value
  from public.petty_cash_requests where id = p_request_id;
  if returned_value > 0 and (nullif(btrim(p_refund_receipt_number), '') is null or p_refund_date is null) then
    raise exception 'Enter the official refund receipt number and return date for unused cash' using errcode = '22023';
  end if;
  liquidation_id := public.submit_contextual_cash_liquidation(
    p_request_id, p_declared_spent, p_note, p_receipts, p_idempotency_key
  );
  update public.petty_cash_liquidations
  set refund_receipt_number = case when returned_value > 0 then btrim(p_refund_receipt_number) else null end,
      refund_date = case when returned_value > 0 then p_refund_date else null end
  where id = liquidation_id and submitted_by = auth.uid();
  return liquidation_id;
end;
$function$

CREATE OR REPLACE FUNCTION eflow_budget.pre_subtask_budget_closeout(p_project_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 result jsonb;
 blockers jsonb;
 p public.projects;
 unallocated numeric;
 returnable numeric;
 task_lines jsonb;
begin
 result:=eflow_phase7.baseline_completion(p_project_id);
 blockers:=result->'blockers';
 select * into p from public.projects where id=p_project_id;
 if p.status not in ('completed','archived') and p.source_collaboration_draft_id is null then
  blockers:=blockers||coalesce((select jsonb_agg(jsonb_build_object('kind','governance','id',p.id,'title',c->>'label','status','review_required','detail',c->>'detail')) from jsonb_array_elements(eflow_phase7.readiness(p.id)->'checks') c where not (c->>'ok')::boolean),'[]'::jsonb);
  blockers:=blockers||coalesce((select jsonb_agg(jsonb_build_object('kind','task','id',t.id,'taskId',t.id,'title',t.title,'status','evidence_required','detail','An approved task submission with completion evidence is required.')) from public.tasks t where t.linked_project_id=p.id and t.deleted_at is null and t.status='completed' and not exists(select 1 from public.task_submissions s where s.task_id=t.id and s.status='approved')),'[]'::jsonb);
 end if;

 -- Previously completed projects retain their existing archive policy.
 if p.status in ('planning','active','on_hold') then
  with active_funds as materialized (
   select f.id, f.amount, f.fiscal_year, f.partition_id
   from eflow_project.funding f
   join public.budget_commitments c on c.id=f.commitment_id and c.status='active'
   where f.project_id=p.id and f.amount>0
  ), task_allocations as materialized (
   select f.id as funding_id, l.id, l.amount, t.title, s.name, f.fiscal_year,
     case when t.linked_project_id=p.id then public.task_budget_line_available(l.id,null) else 0 end as available
   from active_funds f
   join public.work_budget_allocation_lines l on l.project_funding_id=f.id
   join public.work_budget_allocations a on a.id=l.allocation_id and a.subtask_id is null and a.status='approved'
   left join public.tasks t on t.id=a.task_id
   join public.office_budget_sections s on s.id=f.partition_id
  )
  select
   coalesce((select sum(greatest(0,f.amount-coalesce(allocated.amount,0)))
     from active_funds f left join
       (select funding_id,sum(amount) as amount from task_allocations group by funding_id) allocated
       on allocated.funding_id=f.id),0),
   coalesce(sum(available),0),
   coalesce(jsonb_agg(jsonb_build_object('id',id,'task',title,'source',name,'fiscalYear',fiscal_year,'available',available)
     order by title,name,id) filter (where available>0),'[]'::jsonb)
  into unallocated,returnable,task_lines
  from task_allocations;

  if unallocated+returnable>0 then
   blockers:=blockers||jsonb_build_array(jsonb_build_object(
    'kind','funding','id',p.id,'title','Return unused funding to Office Budget','status','release_required',
    'detail','Return unused task allocations to the project first, then have the Head release the remaining project funds to Office Budget before completing.',
    'amount',unallocated+returnable,
    'unusedFunding',jsonb_build_object('unallocated',unallocated,'taskAllocations',task_lines)
   ));
  end if;
 end if;
 return result||jsonb_build_object('blockers',blockers,'canComplete',p.status in ('planning','active','on_hold') and jsonb_array_length(blockers)=0);
end $function$

CREATE OR REPLACE FUNCTION eflow_m7.guard_root_start()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare lead uuid; root jsonb;
begin
 if new.status='in_progress' and old.status in ('todo','pending_assignment','changes_requested') then
  if tg_table_name='tasks' then lead:=old.assigned_to; else lead:=old.lead_id; end if;
  root:=eflow_r7.root(new.id);
  if lead is null or lead is distinct from auth.uid() or not coalesce(eflow_r3.eligible(lead),false)
     or root is not null and not coalesce(eflow_r7.read_root(new.id),false) then
   raise exception 'Only the appointed Task Lead can start this task' using errcode='42501';
  end if;
  if tg_table_name='tasks' and old.status in ('todo','pending_assignment')
     and coalesce((to_jsonb(old)->>'start_date')::date > eflow_m7.work_day(new.id), true) then
   if to_jsonb(old)->>'start_date' is null then
     raise exception 'Set a planned start date before starting this task.' using errcode='22023';
   end if;
   raise exception 'You can start this task on or after %.', to_jsonb(old)->>'start_date' using errcode='22023';
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION eflow_m7.decide_work(p_proposal uuid, p_request uuid, p_approve boolean, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare work eflow_m7.work_proposals; actor uuid:=auth.uid(); note text:=nullif(btrim(p_note),'');
 progress integer;
begin
 if actor is null or p_request is null or p_approve is null or (not p_approve and note is null) or length(note)>3000 then
  raise exception 'Choose a review decision and enter a reason for requested changes' using errcode='22023';
 end if;
 select * into work from eflow_m7.work_proposals where id=p_proposal and (
  state='pending' and eflow_m7.work_reviewer(root_id,node_id,author_id,kind)=actor
  or state<>'pending' and reviewer_id=actor
 );
 if not found or not coalesce(eflow_r7.read_root(work.root_id),false) or not eflow_r3.eligible(actor) then
  raise exception 'Current assigned review required' using errcode='42501';
 end if;
 perform eflow_r7.lock_impact(work.root_id);
 perform 1 from public.tasks where id=work.root_id for update;
 perform 1 from public.personal_tasks where id=work.root_id for update;
 select * into work from eflow_m7.work_proposals where id=p_proposal for update;
 if work.author_id=actor or work.state<>'pending' and work.reviewer_id is distinct from actor then raise exception 'Independent Lead review required' using errcode='42501'; end if;
 if work.decision_request=p_request then
  if work.state is distinct from (case when p_approve then 'approved' else 'changes_requested' end)
     or work.decision_note is distinct from note then raise exception 'Review request terms changed' using errcode='23505'; end if;
  return to_jsonb(work);
 end if;
 if work.state<>'pending' or not eflow_m7.work_scope_open(work.root_id,work.node_id)
    or eflow_m7.work_reviewer(work.root_id,work.node_id,work.author_id,work.kind) is distinct from actor
    or work.submitted_as_lead is distinct from eflow_m7.is_subtask_lead(work.root_id,work.node_id,work.author_id) then
  raise exception 'Review access or work state changed' using errcode='42501';
 end if;
 if work.reviewer_id is distinct from actor then
  update eflow_m7.work_proposals set reviewer_id=actor where id=work.id returning * into work;
  perform eflow_m7.log_proposal(work,'work.proposal_rerouted');
 end if;
 if p_approve then
  if work.baseline is distinct from eflow_m7.work_baseline(work.root_id,work.node_id) then
   raise exception 'Work changed after submission. Return it for a current update.' using errcode='40001';
  end if;
  perform eflow_m7.check_proposal_files(work.terms,work.author_id,work.root_id,work.node_id,work.id);
  insert into eflow_m7.applying_work_proposal values(txid_current(),work.id);
  progress:=(work.terms->>'progress')::integer;
  if exists(select 1 from public.personal_tasks where id=work.root_id) then
   perform eflow_r7.command(work.root_id,(work.baseline->>'revision')::integer,work.id,
    case when work.kind='completion' and work.submitted_as_lead then 'submit' else 'progress' end,
    jsonb_build_object('id',work.node_id,'note',work.terms->>'note','progress',
     coalesce(progress,(select s.percent_complete from public.personal_subtasks s where s.id=work.node_id))));
  elsif work.kind='completion' and work.submitted_as_lead then
   perform eflow_r7.complete_subitem(work.node_id,jsonb_build_object('id',work.id,'note',work.terms->>'note'));
  elsif work.node_id is null then
   perform public.submit_task_progress(work.root_id,progress,null,work.terms->>'blocker',work.terms->>'next_step',work.terms->>'note',null,null);
  elsif progress is not null then
   perform public.save_subtask_progress(work.node_id,progress,null,work.terms->>'blocker',work.terms->>'next_step',work.terms->>'note',null,null);
  else
   perform public.save_subtask_work_update(work.node_id,
    case when nullif(btrim(work.terms->>'blocker'),'') is null then 'in_progress' else 'stuck' end,
    work.terms->>'blocker',work.terms->>'note',work.terms->>'next_step',null,null);
  end if;
  delete from eflow_m7.applying_work_proposal where tx=txid_current() and proposal_id=work.id;
 end if;
 update eflow_m7.work_proposals set state=case when p_approve then 'approved' else 'changes_requested' end,
  decided_at=clock_timestamp(),decision_note=note,decision_request=p_request where id=work.id returning * into work;
 perform eflow_m7.log_proposal(work,case when p_approve then 'work.proposal_approved' else 'work.proposal_changes_requested' end);
 insert into public.notifications(user_id,type,title,message,task_id,actor_id,work_node_id,entity_type,project_id)
 select work.author_id,'status_change',case when p_approve then 'Work update accepted' else 'Changes requested' end,
  'Open the work to see the Lead decision.',work.root_id,actor,work.node_id,
  case when exists(select 1 from public.personal_tasks where id=work.root_id) then 'm7_personal_work_proposal' else 'm7_work_proposal' end,
  (select project_id from public.personal_tasks where id=work.root_id);
 return to_jsonb(work);
end $function$

CREATE OR REPLACE FUNCTION public.m7_start_subtask(p_root uuid, p_node uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor uuid:=eflow_r3.actor(); r jsonb; n eflow_r7.nodes; planned date; started timestamptz;
begin
 if not eflow_r7.read_root(p_root) then raise exception 'Current work access is required' using errcode='42501'; end if;
 perform eflow_r7.lock_impact(p_root);
 r:=eflow_r7.root(p_root);
 if r->>'kind'='office' then
  perform 1 from public.tasks where id=p_root for update;
 else
  perform 1 from public.personal_tasks where id=p_root for update;
 end if;
 r:=eflow_r7.root(p_root);
 if not coalesce(eflow_r7.read_root(p_root),false) then raise exception 'Current work access is required' using errcode='42501'; end if;
 select * into n from eflow_r7.nodes where id=p_node and task_id=p_root;
 if n.id is null or n.lead_id is distinct from actor then
  raise exception 'Only the appointed Subtask Lead can start this subtask' using errcode='42501';
 end if;
 if not coalesce((r->>'open')::boolean,false) or r->>'status'<>'in_progress' then
  raise exception 'The parent task must be in progress before starting this subtask' using errcode='22023';
 end if;
 if r->>'kind'='office' then
  if not exists(select 1 from public.projects where id=(r->>'project')::uuid and status='active') then
   raise exception 'Project is on hold' using errcode='22023';
  end if;
  select start_date,started_at into planned,started from public.subtasks where id=p_node and task_id=p_root for update;
 else
  if not exists(select 1 from public.personal_projects where id=(r->>'project')::uuid and status='active') then
   raise exception 'This project is closed' using errcode='22023';
  end if;
  select start_date,started_at into planned,started from public.personal_subtasks where id=p_node and task_id=p_root for update;
 end if;
 if started is not null then return jsonb_build_object('id',p_node,'started_at',started); end if;
 if n.status <> 'todo' then
  raise exception 'Only a subtask in To do can be started.' using errcode='22023';
 end if;
 if planned is null then
  raise exception 'Set a planned start date before starting this subtask.' using errcode='22023';
 end if;
 if planned > eflow_m7.work_day(p_root) then
  raise exception 'You can start this subtask on or after %.', to_char(planned, 'YYYY-MM-DD') using errcode='22023';
 end if;
 if n.parent_subtask_id is not null and not exists (
  select 1 from eflow_r7.nodes parent where parent.id=n.parent_subtask_id and parent.task_id=p_root
   and case when r->>'kind'='office' then eflow_m7.node_activated(p_root,parent.id)
            else eflow_m7.personal_node_activated(p_root,parent.id) end
 ) then raise exception 'Start the parent subtask first' using errcode='22023'; end if;
 if r->>'kind'='office' and exists(select 1 from public.subtasks s where s.id=p_node and s.dependency_ids is not null) then
   if not eflow_r7.subtask_dependencies_ready(p_root,(select s.dependency_ids from public.subtasks s where s.id=p_node)) then
    raise exception 'Complete every selected prerequisite before starting this subtask.' using errcode='23514';
   end if;
 elsif not n.is_standalone and exists(select 1 from eflow_r7.nodes s where s.task_id=p_root
  and s.parent_subtask_id is not distinct from n.parent_subtask_id and s.sibling_order<n.sibling_order
  and not s.is_standalone and s.status<>'completed') then
  raise exception 'Complete earlier subtasks before starting this subtask' using errcode='22023';
 end if;
 insert into eflow_m7.activation values(txid_current(),p_root);
 if r->>'kind'='office' then
  update public.subtasks set started_at=statement_timestamp() where id=p_node returning started_at into started;
 else
  update public.personal_subtasks set started_at=statement_timestamp() where id=p_node returning started_at into started;
 end if;
 delete from eflow_m7.activation where tx=txid_current() and root=p_root;
 return jsonb_build_object('id',p_node,'started_at',started);
end $function$
